{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e9-preset-craft-vs-plain-t5-20260919T125605Z/cell-xZPelh/src/nodes.js","content":"/**
 * Node shapes produced by the parser and consumed by the renderers.
 *
 * - table: an object; `map` is a Map from key to node, `headerUsed` marks
 *   whether a `[name]` header has already made this exact table current.
 * - arrayOfTables: the array built by repeated `[[name]]` headers; `items`
 *   holds the table nodes in append order.
 * - array: a plain `[ ... ]` value; `items` holds its element nodes.
 * - string / integer / float / boolean: scalars. Integers keep their exact
 *   decimal text (arbitrary precision); floats keep a JS number.
 */

export function makeTable() {
  return { kind: 'table', map: new Map(), headerUsed: false }
}

export function makeArrayOfTables() {
  return { kind: 'arrayOfTables', items: [] }
}

export function makeArray(items) {
  return { kind: 'array', items }
}

export function makeString(value) {
  return { kind: 'string', value }
}

export function makeInteger(text) {
  return { kind: 'integer', text }
}

export function makeFloat(value) {
  return { kind: 'float', value }
}

export function makeBoolean(value) {
  return { kind: 'boolean', value }
}

/** Elements of an array or an array of tables, in order. */
export function elementsOf(node) {
  return node.items
}
"}

