{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e9-preset-craft-vs-plain-t5-20260919T125605Z/cell-xZPelh/src/scan.js","content":"/**
 * Character-level scanning shared by the header and value grammars: skipping
 * spaces/tabs, recognizing blank/comment-only lines, and reading names and
 * quoted strings out of a single line.
 */

import { ParseError } from './parse-error.js'

const BAREWORD_NAME = /[A-Za-z0-9_-]/

export function skipWs(line, pos) {
  while (pos < line.length && (line[pos] === ' ' || line[pos] === '\t')) pos++
  return pos
}

/** True for a line that contributes nothing to the document. */
export function isBlankLine(line) {
  const pos = skipWs(line, 0)
  return pos >= line.length || line[pos] === '#' || line[pos] === ';'
}

/** A bare word or a quoted string, starting at `pos`. */
export function parseName(line, pos, lineNo) {
  if (line[pos] === '"') return parseBasicString(line, pos, lineNo)
  if (line[pos] === "'") return parseLiteralString(line, pos, lineNo)
  const start = pos
  while (pos < line.length && BAREWORD_NAME.test(line[pos])) pos++
  if (pos === start) throw new ParseError(lineNo, 'expected a name')
  return { value: line.slice(start, pos), pos }
}

/** Names joined by `.`, with spaces and tabs allowed around each dot. */
export function parseDottedName(line, pos, lineNo) {
  const first = parseName(line, pos, lineNo)
  const parts = [first.value]
  pos = first.pos
  while (true) {
    const dotPos = skipWs(line, pos)
    if (line[dotPos] !== '.') break
    const afterDot = skipWs(line, dotPos + 1)
    const next = parseName(line, afterDot, lineNo)
    parts.push(next.value)
    pos = next.pos
  }
  return { parts, pos }
}

export function parseBasicString(line, pos, lineNo) {
  pos++ // consume opening quote
  let result = ''
  while (true) {
    if (pos >= line.length) throw new ParseError(lineNo, 'unterminated string')
    const ch = line[pos]
    if (ch === '"') return { value: result, pos: pos + 1 }
    if (ch === '\\') {
      pos++
      if (pos >= line.length) throw new ParseError(lineNo, 'unterminated string')
      const esc = line[pos]
      if (esc === '"') { result += '"'; pos++ }
      else if (esc === '\\') { result += '\\'; pos++ }
      else if (esc === 'n') { result += '\n'; pos++ }
      else if (esc === 't') { result += '\t'; pos++ }
      else if (esc === 'r') { result += '\r'; pos++ }
      else if (esc === '0') { result += '\0'; pos++ }
      else if (esc === 'u') {
        const hex = line.slice(pos + 1, pos + 5)
        if (!/^[0-9A-Fa-f]{4}$/.test(hex)) throw new ParseError(lineNo, 'invalid escape \\u')
        result += String.fromCharCode(parseInt(hex, 16))
        pos += 5
      } else {
        throw new ParseError(lineNo, `invalid escape \\${esc}`)
      }
    } else {
      result += ch
      pos++
    }
  }
}

export function parseLiteralString(line, pos, lineNo) {
  pos++ // consume opening quote
  let result = ''
  while (true) {
    if (pos >= line.length) throw new ParseError(lineNo, 'unterminated string')
    const ch = line[pos]
    if (ch === "'") return { value: result, pos: pos + 1 }
    result += ch
    pos++
  }
}
"}

