 * Turns a parsed document tree into the `json` or `keys` output formats.
 */

function sortedEntries(map) {
  return [...map.keys()].sort().map((key) => [key, map.get(key)])
}

function typeName(node) {
  if (node.kind === 'arrayOfTables') return 'array'
  return node.kind
}

const INDENT = '  '

function toJson(node, depth) {
  switch (node.kind) {
    case 'table': {
      const entries = sortedEntries(node.map)
      if (entries.length === 0) return '{}'
      const body = entries
        .map(([key, value]) => `${INDENT.repeat(depth + 1)}${JSON.stringify(key)}: ${toJson(value, depth + 1)}`)
        .join(',\n')
      return `{\n${body}\n${INDENT.repeat(depth)}}`
    }
    case 'array':
    case 'arrayOfTables': {
      if (node.items.length === 0) return '[]'
      const body = node.items.map((item) => `${INDENT.repeat(depth + 1)}${toJson(item, depth + 1)}`).join(',\n')
      return `[\n${body}\n${INDENT.repeat(depth)}]`
    }
    case 'string':
      return JSON.stringify(node.value)
    case 'integer':
      return node.text
    case 'float':
      return JSON.stringify(node.value)
    case 'boolean':
      return node.value ? 'true' : 'false'
    default:
      throw new Error(`unreachable node kind ${node.kind}`)
  }
}

export function renderJson(root) {
  return `${toJson(root, 0)}\n`
}

function walkKeys(node, path, lines) {
  if (node.kind === 'table') {
    for (const [key, value] of sortedEntries(node.map)) {
      const childPath = path === '' ? key : `${path}.${key}`
      lines.push(`${childPath} ${typeName(value)}`)
      walkKeys(value, childPath, lines)
    }
  } else if (node.kind === 'array' || node.kind === 'arrayOfTables') {
    node.items.forEach((item, index) => {
      const childPath = `${path}[${index}]`
      lines.push(`${childPath} ${typeName(item)}`)
      walkKeys(item, childPath, lines)
    })
  }
}

export function renderKeys(root) {
  const lines = []
  walkKeys(root, '', lines)
  return lines.length === 0 ? '' : `${lines.join('\n')}\n`
}
"}

