    for (const [key, value] of sortedEntries(node.map)) {
      const childPath = path === '' ? key : `${path}.${key}`
      lines.push(`${childPath} ${typeName(value)}`)
      walkKeys(value, childPath, lines)
    }
  } else if (node.kind === 'array' || node.kind === 'arrayOfTables') {
    node.items.forEach((item, index) => {
      const childPath = `${path}[${index}]`
      lines.push(`${childPath} ${typeName(item)}`)
      walkKeys(item, childPath, lines)
    })
  }
}

export function renderKeys(root) {
  const lines = []
  walkKeys(root, '', lines)
  return lines.length === 0 ? '' : `${lines.join('\n')}\n`
}
"}

